// ADR 012 (D25): the workflow picks the next ficha point from one fixed rhythm, one point per message.
// ADR 024: the product the customer wants to customize decides which points the rhythm asks.
const FICHA_RHYTHM = ["product_type","product_model","colors","quantity","artwork_locations","needed_by"];
const MODEL_KINDS = ["roupa","bone","bolsa"];
const POINT_QUESTIONS = {"customer_name":"Qual é o seu nome?","product_type":"O que você quer personalizar: camisetas ou outras roupas, bonés, mochilas e bolsas, ou outro produto?","product_model":{"roupa":"Qual modelo você quer: camiseta comum, manga longa, polo, regata, abadá, baby look ou outro?","bone":"Qual modelo de boné você quer: trucker (com tela atrás), aba curva, aba reta ou outro?","bolsa":"Qual modelo você quer: mochila de costas, mochila saco, ecobag ou outro?","outro":"Qual modelo você quer para cada produto?"},"colors":{"roupa":"Qual a cor da peça?","bone":"Qual a cor do boné?","outro":"Qual cor você quer?"},"quantity":{"roupa":"Quantas peças você precisa?","outro":"Quantas unidades você precisa?"},"artwork_locations":{"roupa":"Onde vai a estampa: só na frente, ou também nas costas ou na manga?","bone":"Onde vai a personalização do boné: na frente, na lateral ou atrás?","outro":"Onde vai a estampa?"},"needed_by":"Para quando você precisa?"};
const PRODUCT_KINDS = [
  ['roupa', /\b(camis\w*|blusas?|polos?|regatas?|abadas?|baby ?looks?|uniformes?|fardas?|moletons?|moletom|jaquetas?|casacos?|agasalhos?|coletes?|bermudas?|shorts?|calcas?|aventa(l|is)|jalecos?|vestidos?|roupas?|manga longa)\b/],
  ['bone', /\b(bones?|viseiras?|chapeus?|toucas?|gorros?)\b/],
  ['bolsa', /\b(mochilas?|bolsas?|sacochilas?|ecobags?|eco ?bags?|sacolas?|necessaires?|pochetes?|estojos?)\b/]
];
// A product that already names its model: the bot does not ask it.
const NAMED_MODELS = {
  roupa: /\b(polos?|regatas?|abadas?|baby ?looks?|moletons?|moletom|jaquetas?|casacos?|coletes?|bermudas?|shorts?|calcas?|aventa(l|is)|jalecos?|vestidos?|manga longa)\b/,
  bone: /\b(trucker|aba (reta|curva)|americanos?|viseiras?|chapeus?|toucas?|gorros?|bucket)\b/,
