    text: 'caneca, squeeze, garrafa e mouse pad costumam ser sublimação' },
  { when: (f) => !isEmptyField(f.customizations) || !isEmptyField(f.numbers),
    text: 'personalização individual: pedir a lista de nomes, números e tamanhos' },
